namespace ElPaqueto.Security.Data;

/// <summary>
/// A user of the package server.
/// </summary>
public class User
{
    /// <summary>Maximum length of a user name.</summary>
    public const int MaxUserNameLength = 64;

    /// <summary>The identifier, generated by the application.</summary>
    public Guid Id { get; set; }

    /// <summary>The user name as entered.</summary>
    public string UserName { get; set; } = string.Empty;

    /// <summary>The upper-invariant form of <see cref="UserName"/>. Unique.</summary>
    public string NormalizedUserName { get; set; } = string.Empty;

    /// <summary>The salted password hash. Never a plain-text password.</summary>
    public string PasswordHash { get; set; } = string.Empty;

    /// <summary>Whether the user may authenticate.</summary>
    public bool IsActive { get; set; }

    /// <summary>The permissions granted to the user.</summary>
    public Permission Permissions { get; set; }

    /// <summary>When the user was created (UTC).</summary>
    public DateTime CreatedAt { get; set; }

    /// <summary>When the user was last updated (UTC).</summary>
    public DateTime UpdatedAt { get; set; }

    /// <summary>When the password was last changed (UTC).</summary>
    public DateTime PasswordChangedAt { get; set; }

    /// <summary>Concurrency token, regenerated on every update.</summary>
    public string ConcurrencyStamp { get; set; } = Guid.NewGuid().ToString("N");

    /// <summary>
    /// Returns the form of a user name that is stored in <see cref="NormalizedUserName"/>.
    /// </summary>
    /// <param name="userName">The user name as entered.</param>
    /// <returns>The normalized user name.</returns>
    public static string Normalize(string userName)
    {
        ArgumentNullException.ThrowIfNull(userName);

        return userName.ToUpperInvariant();
    }
}
